            return
        if kind == 'paper':
            finish(O, 'Kağıt ekstre ve kısa mesaj bu adımda yapabildiğim işlemler değil. ' + S_MENU, 'end_menu')
            return
        try_fail(S, O, prefix, '')
        return
    if stage == 'wwant':
        pw = parse_week(wsaid)
        cw = int((S.get('wk') or dict()).get('cur') or 0)
