NUMW = dict(sifir=0, bir=1, iki=2, uc=3, dort=4, bes=5, alti=6, yedi=7, sekiz=8, dokuz=9)
TENW = dict(on=10, yirmi=20, otuz=30, kirk=40, elli=50, altmis=60, yetmis=70, seksen=80, doksan=90)


def words_to_digits(s):
    """'dört iki beş üç' -> '4253', 'kırk iki elli üç' -> '4253', '42 53' -> '4253'"""
    t = fold(s)
    t = re.sub(r'[^a-z0-9 ]', ' ', t)
    out = ''
    cur = None
    state = ''
    for tok in t.split():
        if tok.isdigit():
            if cur is not None:
                out += str(cur)
                cur = None
            out += tok
            state = ''
            continue
        if tok in TENW:
            if cur is not None:
                out += str(cur)
            cur = TENW[tok]
            state = 'ten'
        elif tok in NUMW:
            v = NUMW[tok]
            if cur is not None and state in ('ten', 'hundred') and v > 0:
                cur = cur + v
                out += str(cur)
                cur = None
                state = ''
            elif cur is not None and state in ('ten', 'hundred'):
                out += str(cur)
                cur = None
                out += str(v)
                state = ''
            else:
                if cur is not None:
                    out += str(cur)
                    cur = None
                cur = v
                state = 'one'
        elif tok == 'yuz':
            base = cur if (cur is not None and state == 'one') else 1
            cur = base * 100
            state = 'hundred'
        elif tok == 'bin':
            base = cur if cur is not None else 1
            cur = None
            out += str(base)
            state = 'thousand'
        else:
            continue
    if cur is not None:
        out += str(cur)
    return out


def parse_week(s):
    t = fold(s).strip()
