            return
        if kind == 'no_card_at_hand' and S.get('sub'):
            try_fail(S, O, prefix, '')
            return
        try_fail(S, O, prefix, '')
        return
    if stage == 'another':
        if said or digits:
            if resolve_card(S, O, V, said, digits, prefix, True):
                return
        if kind == 'yes':
