def kind_var(stage):
    members = dict(STAGE_KINDS[stage])
    for k, v in COMMON_KINDS.items():
        members.setdefault(k, v)
    if stage in ("open", "card", "offer", "another"):
        pass
    desc = LANG_NOTE + "What the customer's last message does. Pick exactly one: " + "; ".join(f"'{k}': {v}" for k, v in members.items()) + \
        ". If the message is only a question back, use 'none'. 'third_party' wins over everything; a specific value wins over 'chatter' and 'unclear'."
    return {"name": f"kind_{stage}", "type": "string", "enum_values": list(members), "description": desc, "min_confidence": 0.3}


