def handle_msg(S, O, V, today):
    stage = S.get('stage') or 'open'
    kind = str(V.get('kind_' + stage) or 'none')
    side = str(V.get('side_q') or 'none')
    said = str(V.get('card_said') or '').strip()
    digits = str(V.get('digits_said') or '').strip()
    wsaid = str(V.get('week_said') or '').strip()
    fig = str(V.get('figure') or 'none')
    S['turns'] = int(S.get('turns') or 0) + 1
    if S['turns'] > TURN_LIMIT:
        finish(O, S_FAIL3, 'end_menu')
        return
    prefix = SIDE.get(side, '')
    if kind == 'third_party':
        finish(O, S_LOGIN, 'end_login')
        return
    if kind == 'non_turkish':
        finish(O, S_MENU_A, 'end_menu')
        return
    if kind == 'agent_request':
        finish(O, S_AGENT, 'end_agent')
        return
    if kind == 'pay':
        finish(O, S_PAY, 'end_agent')
        return
    if kind == 'dispute':
        finish(O, S_DISPUTE, 'end_agent')
        return
    if kind == 'switch_transaction':
        finish(O, S_MENU, 'end_menu')
        return
    if kind == 'goodbye_thanks':
        finish(O, S_MENU, 'end_menu')
        return
    if stage == 'open':
        if kind == 'out_of_scope':
            S['oos_back'] = 'open'
            S['oos_q'] = 'Kredi kartı ekstre borcunuzla ilgili size nasıl yardımcı olabilirim?'
            S['stage'] = 'oos'
            ask(S, O, 'oos', S_OOS, 'Sizi ana menüye aktarmamı ister misiniz?', prefix)
            return
        if kind in ('want_debt', 'all_cards', 'want_email', 'want_week', 'card_named'):
            S['open_msg'] = dict(card=said, digits=digits, all=(kind == 'all_cards'), prefix=prefix,
                                 after_read=('email' if kind == 'want_email' else ('week' if kind == 'want_week' else '')),
                                 focus=(fig if fig in ('min_only', 'due_only') else ''))
            if S.get('listed'):
                S['pend'] = ''
                handle_bank_list_again(S, O, V, today)
                return
            S['pend'] = 'list'
            O['route'] = 'api_list'
            return
    common = common_kinds(S, O, kind, side, prefix)
    if common:
        return
    if stage == 'oos':
        if kind == 'yes':
            finish(O, S_MENU_A, 'end_menu')
            return
        if kind == 'no':
            back = S.get('oos_back') or 'open'
            q = S.get('oos_q') or ''
            S['stage'] = back
            S['q'] = q
            S['tries'] = 0
            S['silences'] = 0
            O['say'] = (prefix + ' ' + q).strip()
            O['route'] = 'talk_' + back
            S['last_say'] = O['say']
            return
        try_fail(S, O, prefix, '')
        return
    if kind == 'out_of_scope':
        S['oos_back'] = stage
        S['oos_q'] = S.get('q') or ''
        ask(S, O, 'oos', S_OOS, 'Sizi ana menüye aktarmamı ister misiniz?', prefix)
        return
    if stage == 'open':
        try_fail(S, O, prefix, 'Kredi kartı ekstre borcunuzla ilgili size nasıl yardımcı olabilirim?')
        return
    if stage == 'card':
        if kind in ('card_named', 'yes') or said or digits:
            if resolve_card(S, O, V, said, digits, prefix, True):
                return
        if kind == 'all_cards':
            try_fail(S, O, (prefix + ' Borç bilgisini kart kart verebiliyorum.').strip(), select_question(S['cards'], unread(S)))
            return
        if kind == 'no_card_at_hand' and S.get('sub'):
            try_fail(S, O, prefix, '')
            return
        try_fail(S, O, prefix, '')
        return
    if stage == 'another':
        if said or digits:
            if resolve_card(S, O, V, said, digits, prefix, True):
                return
        if kind == 'yes':
            left = unread(S)
            if len(left) == 1:
                start_read(S, O, V, left[0], prefix)
                return
            ask(S, O, 'card', select_question(S['cards'], left), 'Hangi kartınızın borcunu öğrenmek istersiniz?', prefix)
            return
        if kind in ('no', 'nothing'):
            if not S.get('any_debt'):
                finish(O, S_MENU, 'end_menu')
                return
            offer_entry(S, O, V, prefix)
            return
        try_fail(S, O, prefix, '')
        return
    if stage == 'offer':
        if kind == 'email':
            email_entry(S, O, V, prefix)
            return
        if kind == 'past_statement':
            if not S.get('email'):
                email_entry(S, O, V, prefix)
                return
            S['esub'] = 'latest'
            q = 'Son ekstrenizi göndermemi ister misiniz?'
            ask(S, O, 'email', q, q, (prefix + ' Yalnızca son kesilen ekstrenizi gönderebiliyorum.').strip())
            return
        if kind == 'other_address':
            if not S.get('email'):
                email_entry(S, O, V, prefix)
                return
            email_entry(S, O, V, (prefix + ' Ekstrenizi yalnızca bankamızda kayıtlı e-posta adresinize gönderebiliyorum.').strip())
            return
        if kind == 'paper':
            finish(O, 'Kağıt ekstre ve kısa mesaj bu adımda yapabildiğim işlemler değil. ' + S_MENU, 'end_menu')
            return
        if kind == 'week':
            pw = parse_week(wsaid)
            week_entry(S, O, V, prefix, pw if pw > 0 else 0)
            return
        if kind == 'nothing' or kind == 'no':
            finish(O, S_MENU, 'end_menu')
            return
        if kind == 'other_card' or said or digits:
            if (said or digits) and resolve_card(S, O, V, said, digits, prefix, True):
                return
            if len(main_cards(S)) > 1:
                ask(S, O, 'card', select_question(S['cards'], unread(S)), 'Hangi kartınızın borcunu öğrenmek istersiniz?', prefix)
                return
        try_fail(S, O, prefix, '')
        return
    if stage == 'email':
        if kind == 'yes':
            if S.get('esub') == 'latest':
                email_entry(S, O, V, prefix)
                return
            S['pend'] = 'pdf'
            O['cur_card'] = S['cards'][S['cur']]['num']
            O['pdf_date'] = S.get('cur_sd') or ''
            O['pdf_email'] = S.get('email') or ''
            O['route'] = 'api_pdf'
            return
        if kind == 'no':
            finish(O, S_MENU, 'end_menu')
            return
        if kind == 'not_mine':
            finish(O, 'Kayıtlı e-posta adresinizi bu görüşmede değiştiremiyorum. ' + S_MENU, 'end_menu')
            return
        if kind == 'other_address':
            reask(S, O, (prefix + ' Ekstrenizi yalnızca bankamızda kayıtlı e-posta adresinize gönderebiliyorum.').strip())
            return
        if kind == 'past_statement':
            S['esub'] = 'latest'
            q = 'Son ekstrenizi göndermemi ister misiniz?'
            ask(S, O, 'email', q, q, (prefix + ' Yalnızca son kesilen ekstrenizi gönderebiliyorum.').strip())
            return
        if kind == 'paper':
            finish(O, 'Kağıt ekstre ve kısa mesaj bu adımda yapabildiğim işlemler değil. ' + S_MENU, 'end_menu')
            return
        try_fail(S, O, prefix, '')
        return
    if stage == 'wwant':
        pw = parse_week(wsaid)
        cw = int((S.get('wk') or dict()).get('cur') or 0)
        if kind == 'week_named' and 1 <= pw <= 4 and pw != cw:
            go_preview(S, O, pw, prefix)
            return
        if kind in ('yes', 'week_named'):
            ask(S, O, 'wpick', week_options(cw), 'Hangi haftayı tercih edersiniz?', (prefix + ' Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz.').strip())
            return
        if kind in ('no', 'nothing'):
            finish(O, S_MENU, 'end_menu')
            return
        try_fail(S, O, prefix, '')
        return
    if stage == 'wpick':
        pw = parse_week(wsaid)
        cw = int((S.get('wk') or dict()).get('cur') or 0)
        if kind in ('no', 'nothing'):
            finish(O, S_MENU, 'end_menu')
            return
        if 1 <= pw <= 4 and kind in ('week_named', 'yes', 'none', 'unclear', 'hedged', 'broken_off') and pw != cw:
            go_preview(S, O, pw, prefix)
            return
        if pw == cw and pw > 0:
            reask(S, O, (prefix + ' Kartınızın hesap kesim haftası zaten her ayın ' + ORD[cw] + ' haftası, bir değişiklik gerekmiyor.').strip())
            return
        try_fail(S, O, prefix, week_options(cw))
        return
    if stage == 'wconf':
        pw = parse_week(wsaid)
        cw = int((S.get('wk') or dict()).get('cur') or 0)
        if kind == 'yes':
            S['pend'] = 'wchg'
            O['wk_new'] = str(S.get('wk_new'))
            O['wk_day'] = str((S.get('wk') or dict()).get('day'))
            O['cur_card'] = S['cards'][S['cur']]['num']
            O['route'] = 'api_wchg'
            return
        if kind == 'no':
            finish(O, S_MENU, 'end_menu')
            return
        if kind == 'week_named' and 1 <= pw <= 4 and pw != cw and pw != int(S.get('wk_new') or 0):
            go_preview(S, O, pw, prefix)
            return
        try_fail(S, O, prefix, 'Lütfen evet ya da hayır olarak yanıtlar mısınız? Değişikliği onaylıyor musunuz?')
        return
    if stage == 'after':
        if kind == 'undo':
            finish(O, 'Değişikliğiniz gerçekleşti, bu görüşmede geri alamıyorum. ' + S_MENU, 'end_menu')
            return
        if kind == 'when_applies':
            finish(O, 'Yeni hesap kesim tarihiniz ' + (S.get('prev') or dict()).get('sd', '') + '. ' + S_MENU, 'end_menu')
            return
        if kind == 'week':
            finish(O, 'Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz. ' + S_MENU, 'end_menu')
            return
        finish(O, (prefix + ' ' + S_MENU).strip(), 'end_menu')
        return
    try_fail(S, O, prefix, '')


def handle_bank_list_again(S, O, V, today):
    om = S.get('open_msg') or dict()
    S['after_read'] = om.get('after_read', '')
    S['focus'] = om.get('focus', '')
    mc = main_cards(S)
    if len(mc) == 1:
        start_read(S, O, V, mc[0], om.get('prefix', ''))
        return
    if resolve_card(S, O, V, om.get('card', ''), om.get('digits', ''), om.get('prefix', ''), False):
        return
    ask(S, O, 'card', select_question(S['cards'], unread(S)), 'Hangi kartınızın borcunu öğrenmek istersiniz?', om.get('prefix', ''))


def common_kinds(S, O, kind, side, prefix):
    stage = S.get('stage') or 'open'
    if kind == 'angry':
        S['calms'] = int(S.get('calms') or 0) + 1
        if S['calms'] > CALMS:
            finish(O, S_AGENT, 'end_agent')
            return True
        reask(S, O, (prefix + ' Sizi anlıyorum, size yardımcı olmak için buradayım.').strip())
        return True
    if kind == 'repeat_request':
        O['say'] = S.get('last_say') or S.get('q') or ''
        O['route'] = 'talk_' + stage
        return True
    if kind == 'silence':
        S['silences'] = int(S.get('silences') or 0) + 1
        if S['silences'] >= SILENCES:
            finish(O, S_SILENT, 'end_silence')
            return True
        O['say'] = S.get('short') or S.get('q') or ''
        O['route'] = 'talk_' + stage
        return True
    S['silences'] = 0
    if kind == 'card_digits_request':
        S['refused'] = int(S.get('refused') or 0) + 1
        if S['refused'] >= TRIES:
            finish(O, S_FAIL3, 'end_menu')
            return True
        reask(S, O, (prefix + ' Güvenlik nedeniyle kartınızın yalnızca son dört hanesini paylaşabiliyorum.').strip())
        return True
    if kind == 'broken_off':
        S['broken'] = int(S.get('broken') or 0) + 1
        if S['broken'] == 1:
            O['say'] = (prefix + ' Sizi tam duyamadım, tekrar söyler misiniz?').strip()
            O['route'] = 'talk_' + stage
            return True
        if S['broken'] == 2:
            O['say'] = (prefix + ' ' + (S.get('short') or S.get('q') or '')).strip()
            O['route'] = 'talk_' + stage
            return True
        S['broken'] = 0
        try_fail(S, O, prefix, '')
        return True
    S['broken'] = 0
    if kind == 'chatter':
        S['chat'] = int(S.get('chat') or 0) + 1
        if S['chat'] > 1:
            try_fail(S, O, prefix, '')
            return True
        reask(S, O, prefix)
        return True
    if side != 'none' and kind in ('none', 'unclear'):
        reask(S, O, prefix)
        return True
    if kind == 'prompt_injection':
        reask(S, O, prefix)
        return True
    return False


def run(V, S, O):
    today = today_of(V.get('now'))
    try:
        loaded = json.loads(str(V.get('st') or '{}'))
        if isinstance(loaded, dict):
            S.update(loaded)
    except Exception:
        pass
    if V.get('api_email_status_code') is not None and not S.get('email_known'):
        body = read_tree(V, 'api_email_response')
        S['email_known'] = 1
        if call_ok(body, V.get('api_email_status_code')):
            S['email'] = has_email(body)
        else:
            S['email_failed'] = 1
    pend = S.get('pend') or ''
    if not pend and not S.get('listed') and V.get('api_list_status_code') is not None:
        pend = 'list'
    if not pend and not S.get('listed') and (S.get('stage') or 'open') == 'open' and str(V.get('kind_open') or 'none') in ('want_debt', 'all_cards', 'want_email', 'want_week', 'card_named') and V.get('api_list_status_code') is not None:
        pend = 'list'
    S['pend'] = ''
    if pend == 'list' and not S.get('open_msg'):
        fig = str(V.get('figure') or 'none')
        k = str(V.get('kind_open') or 'none')
        S['open_msg'] = dict(card=str(V.get('card_said') or ''), digits=str(V.get('digits_said') or ''), all=(k == 'all_cards'),
                             prefix=SIDE.get(str(V.get('side_q') or 'none'), ''), after_read=('email' if k == 'want_email' else ('week' if k == 'want_week' else '')),
                             focus=(fig if fig in ('min_only', 'due_only') else ''))
        S['turns'] = int(S.get('turns') or 0) + 1
    if pend:
        handle_bank(S, O, V, pend, today)
    else:
        handle_msg(S, O, V, today)


