def read_tree(V, prefix):
    out = dict()
    obj = V.get(prefix)
    if isinstance(obj, str) and obj.strip().startswith('{'):
        try:
            obj = json.loads(obj)
        except Exception:
            obj = None
    if isinstance(obj, dict):
        d = obj.get('data')
        if isinstance(d, dict):
            return d
    p = prefix + '.data.'
    for k in list(V.keys()):
        ks = str(k)
        if not ks.startswith(p):
            continue
        parts = ks[len(p):].split('.')
        cur = out
        for part in parts[:-1]:
            if not isinstance(cur.get(part), dict):
                cur[part] = dict()
            cur = cur[part]
        cur[parts[-1]] = V.get(k)
    return out


