# ------------------------------------------------------------------ extraction
COMMON_KINDS = {
    "none": "nothing usable in this message",
    "broken_off": "the message breaks off before the answer to the open question is complete (e.g. 'Benim kartım şey', 'Evet ama')",
    "silence": "the customer says nothing: an empty message, '...', or only a sound",
    "repeat_request": "asks the agent to repeat what it just said ('tekrar eder misiniz', 'anlamadım bir daha söyler misiniz')",
    "agent_request": "explicitly wants a human agent / customer representative ('müşteri temsilcisi', 'bir insanla görüşmek istiyorum'). Asking whether this is a robot is NOT this",
    "pay": "wants to pay the debt now or asks how / where to pay",
    "dispute": "says the debt is wrong, or a payment they made does not show",
    "angry": "is upset, complains, raises their voice or swears, without asking for a person",
    "out_of_scope": "asks something outside this call: interest or late rates, limit, points, miles, instalments, loans, branch hours, next month's bill",
    "switch_transaction": "explicitly wants to do another banking transaction now instead (block card, change address, raise limit)",
    "third_party": "asks about or wants something done on someone else's card (spouse, mother, father, child, friend). This wins over every other value",
    "non_turkish": "the customer speaks a language other than Turkish",
    "goodbye_thanks": "ends the conversation: says goodbye or only thanks and wants nothing more ('teşekkürler, iyi günler', 'görüşürüz')",
    "card_digits_request": "asks the agent to tell them their full card number or its first / middle digits",
    "chatter": "an unrelated remark (weather, the office, their day) with no answer to the question",
    "unclear": "a mumble, a flat refusal to answer, or an answer to some other question. A question back is NOT a refusal",
}
STAGE_KINDS = {
    "open": {"want_debt": "wants to learn their credit card statement debt (may also name a card)",
             "all_cards": "wants the debt of all their cards at once ('bütün kartlarımın borcunu söyle')",
